def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    bg = 0
    for s in range(min(H, W), 1, -1):
        for y in range(H - s + 1):
            for x in range(W - s + 1):
                if (g[y:y+s, x:x+s] == bg).all():
                    g[y:y+s, x:x+s] = 1
                    emit(g, f"Fill the empty {s}x{s} square at rows {y}-{y+s-1}, cols {x}-{x+s-1} with colour 1 (largest squares first, reading order).")
    emit(g, "All remaining empty squares of size >= 2 are filled; this is the final grid.")
    return g
